const D = { froth: .7, swirl: .35, energy: .7, density: .6, speed: 1, scale: 1, hue: 285, x: .5, y: .5, style: 'pearls', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- seed-derived constants (deterministic, rebuild on seed change) ----
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.phiSeed = fr(1) * 6.2831;
  S.asym = (fr(2) - 0.5) * 0.12;   // radius asymmetry between the two generators
  S.rot0 = fr(3) * 6.2831;         // overall orientation
  S.hueSeed = fr(4) * 45;
}

const u = Math.min(width, height);
const t = K.t;
const sec = K.section, inten = K.intensity;
const bass = A.bass || 0, treble = A.treble || 0;

// ---- breathing group parameters: the trace/closeness morph (loose chain <-> dense froth) ----
const breathe = Math.sin(t * 0.11 * (0.4 + P.speed * 0.6)) * 0.05 + Math.sin(t * 0.047) * 0.028;
let rhoBase = 0.42 + P.froth * 0.285 + breathe + inten * 0.02;
const rhoA = Math.max(0.30, Math.min(0.701, rhoBase));
const rhoB = Math.max(0.30, Math.min(0.701, rhoBase * (1 + S.asym)));
const phi = P.swirl * 2.2 + S.phiSeed + t * 0.05 * (0.5 + P.speed) + Math.sin(t * 0.063) * 0.22;
const cp = Math.cos(phi), sp = Math.sin(phi);

// ---- complex helpers ----
function csqrt(x, y) { const r = Math.hypot(x, y); let re = Math.sqrt((r + x) / 2), im = Math.sqrt(Math.max(0, (r - x) / 2)); if (y < 0) im = -im; return [re, im]; }
// normalize a complex 2x2 to det = 1 (proper SL2 Mobius)
function norm(M) {
  const dx = M[0]*M[6] - M[1]*M[7] - (M[2]*M[4] - M[3]*M[5]);
  const dy = M[0]*M[7] + M[1]*M[6] - (M[2]*M[5] + M[3]*M[4]);
  const s = csqrt(dx, dy), sr = s[0], si = s[1], d2 = sr*sr + si*si || 1e-9, o = [];
  for (let i = 0; i < 8; i += 2) { const xr = M[i], xi = M[i+1]; o[i] = (xr*sr + xi*si)/d2; o[i+1] = (xi*sr - xr*si)/d2; }
  return o;
}
function mul(W, g) {
  const a=W[0],ai=W[1],b=W[2],bi=W[3],c=W[4],ci=W[5],d=W[6],di=W[7];
  const e=g[0],ei=g[1],f=g[2],fi=g[3],gg=g[4],gi=g[5],h=g[6],hi=g[7];
  return [a*e-ai*ei + b*gg-bi*gi, a*ei+ai*e + b*gi+bi*gg,
          a*f-ai*fi + b*h-bi*hi,  a*fi+ai*f + b*hi+bi*h,
          c*e-ci*ei + d*gg-di*gi, c*ei+ci*e + d*gi+di*gg,
          c*f-ci*fi + d*h-di*hi,  c*fi+ci*f + d*hi+di*h];
}

// generator matrices — Schottky pairings of 4 circles, normalized to SL2
const rA2 = rhoA*rhoA, rB2 = rhoB*rhoB;
const gA = norm([1,0,  rA2*cp + 1, rA2*sp,  1,0,  1,0]);            // pairs (-1,0)->(+1,0)
const gB = norm([0,1,  rB2*cp - 1, rB2*sp,  1,0,  0,1]);            // pairs (0,-1)->(0,+1)
const gAi = [gA[6],gA[7], -gA[2],-gA[3], -gA[4],-gA[5], gA[0],gA[1]];  // inverse (det=1)
const gBi = [gB[6],gB[7], -gB[2],-gB[3], -gB[4],-gB[5], gB[0],gB[1]];
const GEN = [gA, gAi, gB, gBi];
const INV = [1, 0, 3, 2];   // forbidden immediate inverse

// ---- view ----
const span = 1.34;
const ppu = u * 0.47 * P.scale / span;
const cx = P.x * width, cy = P.y * height;
const theta = S.rot0 + t * (0.03 + P.speed * 0.035) + P.swirl * 0.3;
const style = P.style;
const hb = (P.hue + S.hueSeed + sec * 18) % 360;
const refR = 0.9;
const bigPx = ppu * 0.32;
const maxDepth = Math.floor(5 + P.density * 4.5);
const nodeCap = Math.floor(500 + P.density * 1000);
const alphaMul = P.alpha / 100;
const glowB = Math.min(100, 52 + P.energy * 34 + K.swell * 7 + bass * 26 + inten * 6);

// ---- background / ground tone (fills frame, holds luminance) ----
let bgH, bgS, bgV;
if (style === 'gold-froth') { bgH = 32; bgS = 62; bgV = 8; }
else if (style === 'neon-dust') { bgH = hb; bgS = 55; bgV = 5; }
else if (style === 'ice') { bgH = 202; bgS = 45; bgV = 9; }
else if (style === 'ink') { bgH = 0; bgS = 0; bgV = 5; }
else { bgH = hb; bgS = 48; bgV = 11; }

