  blendMode(ADD); noStroke();
  fill(hb, 42, 46, 10 * alphaMul); ellipse(cx, cy, u * 1.5, u * 1.5);
  fill((hb + 45) % 360, 58, 40, 7 * alphaMul); ellipse(cx, cy, u * 0.85, u * 0.85);
  blendMode(BLEND);
