// ---- draw the Kleinian limit set (reduced-word enumeration) under one rotated frame ----
push();
translate(cx, cy);
rotate(theta);
blendMode(ADD);
if (style === 'ice') { noFill(); strokeWeight(Math.max(0.6, u * 0.0016)); } else noStroke();

let frontier = [];
