let drawn = 0;
const lim = u * 1.85;

for (let depth = 1; depth <= maxDepth && drawn < nodeCap; depth++) {
  const next = [];
  for (let n = 0; n < frontier.length; n++) {
    if (drawn >= nodeCap) break;
    const node = frontier[n], W = node.W;
    drawn++;
    const D2 = W[6]*W[6] + W[7]*W[7];
    if (D2 > 1e-9) {
      let rpx = refR / D2 * ppu;
      if (rpx > bigPx) rpx = bigPx;
      const sx = (W[2]*W[6] + W[3]*W[7]) / D2 * ppu;
      const sy = (W[3]*W[6] - W[2]*W[7]) / D2 * ppu;
      if (Math.abs(sx) < lim && Math.abs(sy) < lim) {
        const dia = Math.max(1.3, rpx * 2);
        const big = rpx > 1.2;                 // a real pearl vs a dust grain
        const fade = big ? Math.min(1, rpx / 6) : 1;
        const gb = glowB * (0.6 + 0.4 * fade);
        if (style === 'gold-froth') {
          const h = 26 + (depth * 4) % 30;
          fill(h, 84, gb, (13 + P.energy * 18) * alphaMul); ellipse(sx, sy, dia, dia);
          if (rpx > 5) { fill(48, 28, 100, 20 * alphaMul); ellipse(sx, sy, rpx * 0.7, rpx * 0.7); }
        } else if (style === 'neon-dust') {
          const h = (hb + depth * 44) % 360;
          fill(h, 96, Math.min(100, gb + 14), (24 + P.energy * 22) * alphaMul); ellipse(sx, sy, big ? dia : 1.6, big ? dia : 1.6);
        } else if (style === 'ice') {
          const h = 188 + (depth * 5) % 40;
          stroke(h, 34, Math.min(100, gb + 15), (22 + P.energy * 26) * alphaMul); ellipse(sx, sy, dia, dia);
        } else if (style === 'ink') {
          fill(0, 0, 90, (9 + P.energy * 13) * alphaMul); ellipse(sx, sy, dia, dia);
          if (rpx > 6) { fill(0, 0, 100, 13 * alphaMul); ellipse(sx, sy, rpx * 0.6, rpx * 0.6); }
        } else { // pearls (default) — depth-hued glowing circles
          const h = (hb + depth * 20) % 360;
          fill(h, 56 + (depth * 7) % 32, gb, (13 + P.energy * 18) * alphaMul); ellipse(sx, sy, dia, dia);
          if (rpx > 4) { fill((h + 18) % 360, 28, 100, 20 * alphaMul); ellipse(sx, sy, rpx * 0.7, rpx * 0.7); }
        }
        // treble sparkle on brightest pearls (audio on top of clk baseline; zero-safe)
        if (treble > 0.03 && big && style !== 'ink' && style !== 'ice') {
          fill((hb + 60) % 360, 22, 100, treble * 24 * alphaMul); ellipse(sx, sy, dia * 0.6, dia * 0.6);
        }
      }
    }
    if (depth < maxDepth) {
      const forbid = INV[node.last];
      for (let k = 0; k < 4; k++) { if (k === forbid) continue; next.push({ W: mul(W, GEN[k]), last: k }); }
    }
  }
  frontier = next;
}
blendMode(BLEND);
pop();
